/**
 * =============================================================================
 * KS-1215 — the connector branch never carries the caller's Bearer
 * =============================================================================
 * A request with a VALID `x-api-key` takes authenticateToken's connector branch:
 * req.user becomes the connector, and the key is exchanged at auth for a
 * short-lived connector JWT that is set as Authorization. When that exchange
 * failed (a refusal, a dropped connection, an unparseable body), the helper
 * returned null and Authorization was left as the CALLER sent it, so the
 * caller's own Bearer reached the upstream beside the connector principal:
 *   - a REVOKED session's JWT plus a valid key was forwarded past the
 *     session-revocation check (the N-1 of the KS-1207 gate);
 *   - a LIVE user's JWT travelled under the connector principal (a split
 *     principal).
 *
 * Now the branch drops the caller's Authorization first, before any await
 * (Wednesday's ruling O3, 2026-09-17 11:22:22Z). A successful exchange sets the
 * connector JWT as before; a failed one forwards no Bearer.
 *
 * Residual, by design: a revoked-JWT holder with a VALID key still acts as the
 * connector, which the key alone already grants. Not covered: /api/batch/*.
 *
 * Pre-gate fix round: POST /api/platform/organizations/register-connector built its
 * upstream Authorization from `rawAuthorization`, the copy index.ts takes before any
 * auth runs, so the caller's Bearer still reached /api/tenants, the key mint
 * /api/keys and /api/audit on the connector branch. It now forwards the header the
 * auth middleware left in place: the connector JWT for a connector, the admin's own
 * Bearer for a JWT-only admin.
 *
 * Real app (the ks1207 pattern): the app exported by index.ts, `../db` mocked,
 * every upstream pointed at one recording stub that also answers key validation
 * and the connector-token exchange. The session store is stubbed: session
 * `ks1215-revoked` is revoked, `ks1215-live` is live. One cell repeats N-1 under
 * NODE_ENV=production on /api/v1 (the ks871 production recipe).
 *
 * The STRUCTURAL cells call the middleware directly (the ks480 pattern). At
 * runtime the helper never rejects: it catches every failure and returns null,
 * so "delete only when the exchange fails" and "delete first" behave the same on
 * every runtime cell above. The structural cells make the helper reject and
 * check that the caller's Bearer was already gone, which only "delete first,
 * before any await" satisfies. No runtime path makes this helper reject today;
 * they guard a future change to it.
 * =============================================================================
 */
import { describe, it, expect, beforeAll, afterAll, vi } from 'vitest';
import http from 'http';
import jwt from 'jsonwebtoken';
import type { AddressInfo } from 'net';
import type { Request, Response } from 'express';

vi.mock('../db', async (orig) => {
  const real = (await orig()) as Record<string, unknown>;
  return {
    ...real,
    isDbAvailable: () => true,
    // register-connector inserts the Organisation and reads back its id and slug.
    query: async (sql: string) => (/INSERT INTO organizations/i.test(sql)
      ? { rows: [{ id: 'd0000000-0000-4000-8000-000000001215', slug: 'ks1215-org' }], rowCount: 1 }
      : { rows: [], rowCount: 0 }),
  };
});

const sessionChecks: string[] = [];
vi.mock('@secuura/shared', async (orig) => {
  const real = (await orig()) as Record<string, unknown>;
  return {
    ...real,
    isSessionActive: async (sessionId: string) => {
      sessionChecks.push(sessionId);
      return sessionId === 'ks1215-revoked' ? false : sessionId === 'ks1215-live' ? true : null;
    },
  };
});

const PRIV = process.env.__TEST_JWT_PRIVATE_PEM as string;
const TENANT = 'a0000000-0000-4000-8000-000000000001';
const OK_KEY = 'sk_ks1215_exchange_ok_00001';
const REFUSED_KEY = 'sk_ks1215_exchange_401_0001';
const DROPPED_KEY = 'sk_ks1215_exchange_drop_001';
const CONNECTOR_ID: Record<string, string> = { [OK_KEY]: 'ks1215-ok', [REFUSED_KEY]: 'ks1215-refused', [DROPPED_KEY]: 'ks1215-dropped' };

type Hit = { url: string; userId: string | null; bearer: string };
const hits: Hit[] = [];
const INFRA = (url: string) => url === '/api/keys/validate' || url === '/internal/connector-token' || url.startsWith('/.well-known/');

const RAN = new Set<string>();

function readBody(req: http.IncomingMessage): Promise<string> {
  return new Promise((r) => { const c: Buffer[] = []; req.on('data', (d) => c.push(d)); req.on('end', () => r(Buffer.concat(c).toString())); });
}
const REGISTER_UPSTREAMS = ['/api/audit', '/api/keys', '/api/tenants'];
async function listen(server: http.Server): Promise<string> {
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', () => resolve()));
  return `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
}
async function closeServer(server: http.Server | undefined): Promise<void> {
  if (!server) return;
  server.closeAllConnections();
  await new Promise<void>((r) => server.close(() => r()));
}

/** What reached the upstream as Authorization: none, the connector JWT, or a user's JWT named by its session. */
function bearerOf(header: string | undefined): string {
  if (!header) return 'none';
  const decoded = jwt.decode(header.replace(/^Bearer\s+/i, '')) as Record<string, unknown> | null;
  if (!decoded) return 'undecodable';
  return decoded.type === 'connector' ? 'connector-jwt' : `user:${String(decoded.sessionId)}`;
}

type Res = { status: number; code: string | null; forwarded: Hit[] };
function send(base: string, path: string, headers: Record<string, string>): Promise<Res> {
  return new Promise((resolve, reject) => {
    const target = new URL(base);
    const before = hits.length;
    const req = http.request({ hostname: target.hostname, port: target.port, path, method: 'GET', agent: false, headers }, (res) => {
      const c: Buffer[] = [];
      res.on('data', (d) => c.push(d));
      res.on('end', () => {
        let code: string | null = null;
        try { code = JSON.parse(Buffer.concat(c).toString())?.error?.code ?? null; } catch { /* non-JSON: code stays null */ }
        // Give a forwarded request time to land before reading the recorder.
        setTimeout(() => resolve({ status: res.statusCode ?? 0, code, forwarded: hits.slice(before) }), 50);
      });
    });
    req.setTimeout(15000, () => req.destroy(new Error(`no response from ${path} within 15 s`)));
    req.on('error', reject);
    req.end();
  });
}

function userJwt(sessionId: string): string {
  return 'Bearer ' + jwt.sign(
    { userId: 'u-ks1215', email: 'ks1215-user@secuura.io', role: 'user', verificationLevel: 'email', authMethod: 'email', tenantId: TENANT, sessionId },
    PRIV,
    { algorithm: 'RS256', expiresIn: '10m' },
  );
}

function adminJwt(sessionId: string): string {
  return 'Bearer ' + jwt.sign(
    { userId: 'u-ks1215-admin', email: 'ks1215-admin@secuura.io', role: 'SYSTEM_ADMIN', verificationLevel: 'email', authMethod: 'email', tenantId: TENANT, sessionId },
    PRIV,
    { algorithm: 'RS256', expiresIn: '10m' },
  );
}

/** POST a JSON body; waits long enough for register-connector's fire-and-forget audit call to land. */
function post(base: string, path: string, headers: Record<string, string>, body: unknown): Promise<Res> {
  return new Promise((resolve, reject) => {
    const target = new URL(base);
    const before = hits.length;
    const payload = JSON.stringify(body);
    const req = http.request({ hostname: target.hostname, port: target.port, path, method: 'POST', agent: false,
      headers: { 'content-type': 'application/json', 'content-length': String(Buffer.byteLength(payload)), ...headers } }, (res) => {
      const c: Buffer[] = [];
      res.on('data', (d) => c.push(d));
      res.on('end', () => {
        let code: string | null = null;
        try { code = JSON.parse(Buffer.concat(c).toString())?.error?.code ?? null; } catch { /* non-JSON */ }
        setTimeout(() => resolve({ status: res.statusCode ?? 0, code, forwarded: hits.slice(before) }), 250);
      });
    });
    req.setTimeout(15000, () => req.destroy(new Error(`no response from ${path} within 15 s`)));
    req.on('error', reject);
    req.end(payload);
  });
}
let externalRefSeq = 0;
function registerBody(): Record<string, unknown> {
  externalRefSeq += 1;
  return { externalRef: `ks1215-ext-${externalRefSeq}`, organizationName: `KS1215 Org ${externalRefSeq}`, tenantSlug: 'ks1215-tenant' };
}
/** The Bearer each of register-connector's three upstream calls received, keyed by path. */
function registerBearers(r: Res): Record<string, string> {
  // Keys sorted, so the JSON comparison below does not depend on the order the calls arrive in.
  return Object.fromEntries(r.forwarded.filter((h) => REGISTER_UPSTREAMS.includes(h.url)).map((h) => [h.url, h.bearer]).sort(([x], [y]) => x.localeCompare(y)));
}
const allThree = (bearer: string) => ({ '/api/audit': bearer, '/api/keys': bearer, '/api/tenants': bearer });

/** One upstream for every service: key validation, the connector-token exchange, and a recorder for everything else. */
function createUpstream(): http.Server {
  return http.createServer(async (req, res) => {
    const body = await readBody(req);
    const json = (status: number, payload: unknown) => { res.writeHead(status, { 'content-type': 'application/json' }); res.end(JSON.stringify(payload)); };
    const url = req.url || '';
    if (url === '/api/keys/validate') {
      const key = JSON.parse(body || '{}').key as string;
      return json(200, CONNECTOR_ID[key]
        ? { data: { valid: true, connectorId: CONNECTOR_ID[key], scopes: ['documents:read', 'documents:write', 'organizations:register'], organizationId: 'org-ks1215', tenantId: TENANT, rateLimit: 1000, rateLimitWindow: 60 } }
        : { data: { valid: false } });
    }
    if (url === '/internal/connector-token') {
      const key = JSON.parse(body || '{}').apiKey as string;
      if (key === DROPPED_KEY) { req.socket.destroy(); return; }
      if (key !== OK_KEY) return json(401, { success: false });
      const token = jwt.sign({ userId: 'connector:ks1215-ok', email: 'connector@secuura.io', role: 'connector', verificationLevel: 'api_key', type: 'connector' }, PRIV, { algorithm: 'RS256', expiresIn: 600 });
      return json(200, { success: true, data: { token, expiresIn: 600 } });
    }
    if (url.startsWith('/.well-known/')) return json(404, {});
    if (!INFRA(url)) hits.push({ url, userId: (req.headers['x-user-id'] as string | undefined) ?? null, bearer: bearerOf(req.headers.authorization as string | undefined) });
    // register-connector's three upstream calls: the tenant lookup, the key mint and the audit write.
    if (url === '/api/tenants') return json(200, { tenants: [{ id: TENANT, slug: 'ks1215-tenant' }] });
    if (url === '/api/keys') return json(201, { success: true, data: { id: 'key-ks1215', key: 'sk_minted_ks1215', prefix: 'sk_mint' } });
    if (url === '/api/audit') return json(201, { success: true });
    return json(200, { success: true, data: { recorder: true } });
  });
}

const SERVICES = ['ANALYTICS', 'ANCHORING', 'AUTH', 'BILLING', 'GOVERNANCE', 'KYC', 'NFT', 'NOTIFICATION', 'ORIGINATE', 'PRISM',
  'REFERRAL', 'SECURITY', 'STAKING', 'TIMESTAMPING', 'TRANSFER', 'VC_ISSUER', 'WALLET'];

async function bootApp(upstreamUrl: string): Promise<{ server: http.Server; url: string }> {
  for (const name of SERVICES) vi.stubEnv(`${name}_SERVICE_URL`, upstreamUrl);
  vi.stubEnv('TENANT_PROVISIONING_URL', upstreamUrl);
  vi.stubEnv('GATEWAY_VOUCH_SECRET', '');
  delete process.env.JWT_JWKS_URL;
  vi.resetModules();
  const app = (await import('../index')).default;
  const server = http.createServer(app as http.RequestListener);
  return { server, url: await listen(server) };
}

let upstream: http.Server | undefined;
let upstreamUrl = '';
beforeAll(async () => {
  upstream = createUpstream();
  upstreamUrl = await listen(upstream);
});
afterAll(async () => {
  await closeServer(upstream);
  vi.unstubAllEnvs();
});

// An optional mount (authenticateToken(false)) and a required one (authenticateToken(true)).
const MOUNTS: Array<[string, string]> = [
  ['optional /api/credentials', '/api/credentials/cred-ks1215'],
  ['required /api/documents', '/api/documents/doc-ks1215'],
];

describe('KS-1215 real app, NODE_ENV=test — a failed connector-token exchange forwards no caller Bearer', () => {
  let gateway: { server: http.Server; url: string } | undefined;
  beforeAll(async () => {
    vi.stubEnv('NODE_ENV', 'test');
    gateway = await bootApp(upstreamUrl);
  }, 60000);
  afterAll(async () => { await closeServer(gateway?.server); });

  for (const [mount, path] of MOUNTS) {
    it(`🔴 ${mount} N-1: a valid key + a REVOKED session's JWT, exchange refused, reaches the upstream with no Bearer`, async () => {
      RAN.add(`${mount} N-1`);
      const r = await send(gateway!.url, path, { 'x-api-key': REFUSED_KEY, authorization: userJwt('ks1215-revoked') });
      expect([r.status, r.forwarded.map((h) => h.userId), r.forwarded.map((h) => h.bearer)]).toEqual([200, ['connector:ks1215-refused'], ['none']]);
    });

    it(`🔴 ${mount} split principal: a valid key + a LIVE user's JWT, exchange refused, does not forward the user's Bearer`, async () => {
      RAN.add(`${mount} split`);
      const r = await send(gateway!.url, path, { 'x-api-key': REFUSED_KEY, authorization: userJwt('ks1215-live') });
      expect([r.status, r.forwarded.map((h) => h.userId), r.forwarded.map((h) => h.bearer)]).toEqual([200, ['connector:ks1215-refused'], ['none']]);
    });

    it(`🔴 ${mount} unreachable: the exchange connection drops, and neither a live nor a revoked caller's Bearer is forwarded`, async () => {
      RAN.add(`${mount} unreachable`);
      const live = await send(gateway!.url, path, { 'x-api-key': DROPPED_KEY, authorization: userJwt('ks1215-live') });
      const revoked = await send(gateway!.url, path, { 'x-api-key': DROPPED_KEY, authorization: userJwt('ks1215-revoked') });
      expect([live.status, live.forwarded.map((h) => h.bearer), revoked.status, revoked.forwarded.map((h) => h.bearer)]).toEqual([200, ['none'], 200, ['none']]);
    });

    it(`control, ${mount}: exchange OK, a key alone forwards the connector JWT`, async () => {
      RAN.add(`${mount} control key alone`);
      const r = await send(gateway!.url, path, { 'x-api-key': OK_KEY });
      expect([r.status, r.forwarded.map((h) => h.userId), r.forwarded.map((h) => h.bearer)]).toEqual([200, ['connector:ks1215-ok'], ['connector-jwt']]);
    });

    it(`control, ${mount}: exchange OK, a key beside a live JWT forwards the connector JWT, not the user's`, async () => {
      RAN.add(`${mount} control key + live`);
      const r = await send(gateway!.url, path, { 'x-api-key': OK_KEY, authorization: userJwt('ks1215-live') });
      expect([r.status, r.forwarded.map((h) => h.userId), r.forwarded.map((h) => h.bearer)]).toEqual([200, ['connector:ks1215-ok'], ['connector-jwt']]);
    });

    it(`control, ${mount}: a live JWT alone is forwarded with the user's own Bearer after its session is checked`, async () => {
      RAN.add(`${mount} control live alone`);
      const before = sessionChecks.length;
      const r = await send(gateway!.url, path, { authorization: userJwt('ks1215-live') });
      expect([r.status, r.forwarded.map((h) => h.userId), r.forwarded.map((h) => h.bearer)]).toEqual([200, ['u-ks1215'], ['user:ks1215-live']]);
      expect(sessionChecks.slice(before)).toContain('ks1215-live');
    });
  }
  it('RED: a connector key is refused 403 on GET /api/platform/tenants and nothing is forwarded', async () => {
    RAN.add('platform tenants GET refuses a connector');
    const tg = await send(gateway!.url, '/api/platform/tenants', { 'x-api-key': OK_KEY });
    expect([tg.status, tg.code, tg.forwarded.map((h) => h.url)]).toEqual([403, 'FORBIDDEN', []]);
  });
  it('RED KS-1238 (i): a valid key + a REVOKED session JWT under a lower-case or upper-case bearer scheme, exchange refused, reaches the upstream with no Bearer', async () => {
    RAN.add('KS-1238 (i) bearer scheme case');
    const token = userJwt('ks1215-revoked').slice('Bearer '.length);
    const lower = await send(gateway!.url, '/api/documents/doc-ks1215', { 'x-api-key': REFUSED_KEY, authorization: 'bearer ' + token });
    const upper = await send(gateway!.url, '/api/documents/doc-ks1215', { 'x-api-key': REFUSED_KEY, authorization: 'BEARER ' + token });
    expect(JSON.stringify([lower.status, lower.forwarded.map((h) => h.bearer), upper.status, upper.forwarded.map((h) => h.bearer)])).toBe(JSON.stringify([200, ['none'], 200, ['none']]));
  });
});

