describe('KS-1215 real app, NODE_ENV=test — register-connector forwards no caller Bearer upstream', () => {
  let gateway: { server: http.Server; url: string } | undefined;
  beforeAll(async () => {
    vi.stubEnv('NODE_ENV', 'test');
    gateway = await bootApp(upstreamUrl);
  }, 60000);
  afterAll(async () => { await closeServer(gateway?.server); });
  const PATH = '/api/platform/organizations/register-connector';

  it('🔴 register-connector: a valid key + a REVOKED session\'s JWT sends no caller Bearer to /api/tenants, /api/keys or /api/audit, whether the exchange succeeds or is refused', async () => {
    RAN.add('register revoked');
    const ok = await post(gateway!.url, PATH, { 'x-api-key': OK_KEY, authorization: userJwt('ks1215-revoked') }, registerBody());
    const refused = await post(gateway!.url, PATH, { 'x-api-key': REFUSED_KEY, authorization: userJwt('ks1215-revoked') }, registerBody());
    // Compared as JSON so a red prints every forwarded Bearer (vitest truncates nested objects).
    expect(JSON.stringify([ok.status, registerBearers(ok), refused.status, registerBearers(refused)]))
      .toBe(JSON.stringify([201, allThree('connector-jwt'), 201, allThree('none')]));
