  it('🔴 register-connector: a valid key + a LIVE user\'s JWT sends the connector JWT, not the user\'s Bearer, to all three upstream calls', async () => {
    RAN.add('register live');
    const r = await post(gateway!.url, PATH, { 'x-api-key': OK_KEY, authorization: userJwt('ks1215-live') }, registerBody());
    expect(JSON.stringify([r.status, registerBearers(r)])).toBe(JSON.stringify([201, allThree('connector-jwt')]));
  });

  it('RED register-connector: a valid key + a LIVE user\'s JWT, exchange REFUSED, sends no caller Bearer to /api/tenants, /api/keys or /api/audit', async () => {
    RAN.add('register live refused');
    const liveRefused = await post(gateway!.url, PATH, { 'x-api-key': REFUSED_KEY, authorization: userJwt('ks1215-live') }, registerBody());
