    const r = await post(gateway!.url, '/api/platform/tenants', { 'x-api-key': OK_KEY }, { name: 'KS1238 Tenant', slug: 'ks1238-tenant' });
    expect([r.status, r.code, r.forwarded.map((h) => h.url)]).toEqual([403, 'FORBIDDEN', []]);
  });
  it('RED KS-1238 (iii): a super-admin JWT on POST /api/platform/tenants reaches tenant-provisioning and refresh-tenants with its own post-auth Bearer', async () => {
    RAN.add('KS-1238 (iii) super-admin tenants');
    const sa = await post(gateway!.url, '/api/platform/tenants', { authorization: adminJwt('ks1215-live') }, { name: 'KS1238 SA Tenant', slug: 'ks1238-sa-tenant' });
    expect([sa.status, sa.forwarded.map((h) => [h.url, h.bearer])]).toEqual([200, [['/api/tenants', 'user:ks1215-live'], ['/api/admin/refresh-tenants', 'user:ks1215-live']]]);
  });
  it('control, register-connector: a JWT-only platform admin still succeeds, and all three upstream calls carry the admin\'s own Bearer', async () => {
    RAN.add('register admin control');
    const r = await post(gateway!.url, PATH, { authorization: adminJwt('ks1215-live') }, registerBody());
    expect(JSON.stringify([r.status, registerBearers(r)])).toBe(JSON.stringify([201, allThree('user:ks1215-live')]));
  });

  it('control, register-connector: a key alone is unchanged, and all three upstream calls carry the connector JWT', async () => {
    RAN.add('register key-only control');
    const r = await post(gateway!.url, PATH, { 'x-api-key': OK_KEY }, registerBody());
    expect(JSON.stringify([r.status, registerBearers(r)])).toBe(JSON.stringify([201, allThree('connector-jwt')]));
  });
});

describe('KS-1215 STRUCTURAL — the caller Bearer is gone before the exchange is awaited', () => {
  const CALLER = 'Bearer ks1215.caller.jwt';
  const KEY = 'sk_ks1215_structural_key_01';

  // structural: no runtime path makes this helper reject today; guards a future helper change.
  async function callWithRejectingHelper(required: boolean) {
    const auth = await import('../middleware/auth');
    auth.apiKeyCache.set(KEY, {
      result: { connectorId: 'ks1215-structural', scopes: ['documents:read'], organizationId: 'org-ks1215', tenantId: TENANT, tenantSlug: '', rateLimit: 1000, rateLimitWindow: 60 },
      expiresAt: Date.now() + 60_000,
    });
    const planted = new Error('ks1215 structural: the connector-token helper rejected');
    const cache = auth.connectorBearerCache;
    const realGet = cache.get;
    // getConnectorBearer reads this cache before its try block, so a throw here makes the helper itself reject.
    Object.defineProperty(cache, 'get', {
      configurable: true, writable: true,
      value: function (this: typeof cache, k: string) { if (k === KEY) throw planted; return realGet.call(this, k); },
    });
    try {
      const req = { headers: { 'x-api-key': KEY, authorization: CALLER }, get(name: string) { return (this as any).headers[name?.toLowerCase()]; } } as unknown as Request;
      const res = { status() { return res; }, json() { return res; } } as unknown as Response;
      const next = vi.fn();
      let rejected: unknown = null;
      try { await auth.authenticateToken(required)(req, res, next); } catch (err) { rejected = err; }
      return { planted, rejected, authorization: req.headers.authorization };
    } finally {
      delete (cache as unknown as Record<string, unknown>).get;
      auth.apiKeyCache.delete(KEY);
    }
  }

  for (const required of [false, true]) {
    it(`🔴 STRUCTURAL (no runtime path makes this helper reject today; guards a future helper change): authenticateToken(${required}), the caller's Bearer is already gone when the helper rejects`, async () => {
      RAN.add(`structural required=${required}`);
      const r = await callWithRejectingHelper(required);
      expect(r.rejected, 'the planted rejection reached the middleware (else this cell proves nothing)').toBe(r.planted);
      expect(r.authorization).toBeUndefined();
    });
